  "flashcards": [
    {
      "id": "fc-01",
      "front": "Quelle séquence physiopathologique décrit le cancer colorectal sporadique ?",
      "back": "La séquence adénome-carcinome : accumulation de mutations menant du polype adénomateux à l'adénocarcinome.",
      "tags": [
        "physiopathologie"
      ]
    },
    {
      "id": "fc-02",
      "front": "Quel examen fait le diagnostic du cancer colorectal ?",
      "back": "La coloscopie avec biopsies.",
      "tags": [
        "diagnostic"
      ]
    },
    {
      "id": "fc-03",
      "front": "Quelle différence clinique entre cancer du côlon droit et du côlon gauche ?",
      "back": "Côlon droit : anémie ferriprive et douleurs vagues ; côlon gauche : troubles du transit, rectorragies, occlusion.",
      "tags": [
        "clinique"
      ]
    },
    {
      "id": "fc-04",
      "front": "Quel examen est indispensable au staging du cancer du rectum ?",
      "back": "L'IRM pelvienne, qui évalue l'infiltration du mésorecte et la marge circonférentielle.",
      "tags": [
        "extension"
      ]
    },
    {
      "id": "fc-05",
      "front": "Quelle est la place de la radiochimiothérapie dans le cancer du rectum ?",
      "back": "Préopératoire pour les formes localement avancées, afin de réduire la récidive locale et faciliter une chirurgie de qualité.",
      "tags": [
        "traitement"
      ]
    },
    {
      "id": "fc-06",
      "front": "Quel geste chirurgical référence pour le cancer du rectum ?",
      "back": "L'excision totale du mésorecte.",
      "tags": [
        "traitement"
      ]
    },
    {
      "id": "fc-07",
      "front": "Quel marqueur sert de référence pour le suivi ?",
      "back": "L'antigène carcino-embryonnaire (ACE).",
      "tags": [
        "surveillance"
      ]
    },
    {
      "id": "fc-08",
      "front": "Quels syndromes héréditaires prédisposent au cancer colorectal ?",
      "back": "Le syndrome de Lynch et la polypose adénomateuse familiale.",
      "tags": [
        "génétique"
      ]
    },
    {
      "id": "fc-09",
      "front": "Quel organe est le site métastatique dominant ?",
      "back": "Le foie.",
      "tags": [
        "extension"
      ]
    },
